/*
 * tiny_reference_manifest.rs — the Tier T fixture is what its manifest says.
 *
 * The tiny transformers-authored fixture is generated by torch and committed,
 * which means it cannot be regenerated where it is checked. Every other
 * fixture in this workspace is written by synth.rs and byte-compared against a
 * fresh generation, so drift is impossible; this one has to be guarded a
 * different way.
 *
 * The manifest is that guard. It records sha256 of each artifact and of the
 * generator script, so editing the generator without re-running it on the
 * workstation fails here -- in the sandbox, with no torch -- rather than
 * silently leaving a capture of a model that no longer exists. That is the
 * half of the mistake that is easy to make: the edit is one line and the
 * regeneration is a trip to another machine.
 *
 * It skips when the fixture is absent, because the generator has not been run
 * yet. A skip is loud (see the [SKIP] contract in .styles/RUST_STYLE.md) and
 * a missing fixture is exactly the state this repository is in until the
 * workstation produces one.
 */

use std::path::{Path, PathBuf};

use runtime::digest::sha256_hex;

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures/tiny-hf-gemma4")
}

fn read_json(path: &Path) -> serde_json::Value {
    let text =
        std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {}: {e}", path.display()))
}

#[test]
fn every_committed_artifact_matches_the_hash_the_manifest_records() {
    let dir = fixture_dir();
    let manifest_path = dir.join("manifest.json");
    if !manifest_path.exists() {
        runtime::testlog::skip(
            "tiny transformers fixture",
            "fixtures/tiny-hf-gemma4 has not been generated; \
             run fixtures/build_tiny_reference.py on the workstation",
        );
        return;
    }
    let manifest = read_json(&manifest_path);
    let artifacts = manifest["artifacts"]
        .as_object()
        .expect("manifest carries no artifacts object");
    assert!(
        !artifacts.is_empty(),
        "manifest lists no artifacts, so it guards nothing"
    );

    for (name, want) in artifacts {
        let path = dir.join(name);
        let bytes = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("manifest names {name}, which cannot be read: {e}"));
        let got = sha256_hex(&bytes);
        assert_eq!(
            got,
            want.as_str().unwrap_or_default(),
            "{name} does not match the manifest: regenerate the fixture with \
             fixtures/build_tiny_reference.py on the workstation, or restore the file"
        );
    }
}

#[test]
fn the_generator_has_not_been_edited_since_the_fixture_was_built() {
    // The point of hashing the generator, and the reason this is a separate
    // test from the one above: an edited generator with unregenerated
    // artifacts is a fixture that no longer means what the script says it
    // means, and every artifact hash still matches, so the test above passes.
    let dir = fixture_dir();
    let manifest_path = dir.join("manifest.json");
    if !manifest_path.exists() {
        runtime::testlog::skip(
            "tiny fixture generator",
            "fixtures/tiny-hf-gemma4 has not been generated",
        );
        return;
    }
    let manifest = read_json(&manifest_path);
    let generator =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures/build_tiny_reference.py");
    let bytes = std::fs::read(&generator).expect("read the generator");
    assert_eq!(
        sha256_hex(&bytes),
        manifest["generator_sha256"].as_str().unwrap_or_default(),
        "build_tiny_reference.py has changed since the fixture was built; \
         re-run it on the workstation and commit what it writes"
    );
}

#[test]
fn the_manifest_records_what_produced_the_fixture() {
    // A fixture is reproducible only if the versions and the seed that made
    // it are written down. transformers in particular: an upgrade that
    // changes Gemma 4 semantics has to be a visible diff here rather than a
    // silently moved oracle.
    let manifest_path = fixture_dir().join("manifest.json");
    if !manifest_path.exists() {
        runtime::testlog::skip("tiny fixture provenance", "fixture not generated");
        return;
    }
    let manifest = read_json(&manifest_path);
    for key in ["transformers", "torch"] {
        let value = manifest[key].as_str().unwrap_or_default();
        assert!(!value.is_empty(), "manifest records no {key} version");
    }
    assert!(
        manifest["seed"].is_number(),
        "manifest records no seed, so the weights cannot be reproduced"
    );
}
